/// A yes-or-no fact about a relic.
///
/// Nine separate `RelicModel` members rather than a game enum, so the
/// numbering is the order the dump writes the columns in.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[repr(u8)]
pub enum RelicFlag {
    /// Spent, and gone once it fires.
    UsedUp = 0,
    /// Does something the moment it is picked up, rather than in combat.
    UponPickup = 1,
    /// Brings a pet along.
    SpawnsPets = 2,
    /// More than one can be held. Two relics stack, both of them
    /// `Undrafted`.
    Stackable = 3,
    /// Adds a pet to the party.
    AddsPet = 4,
    /// A merchant may stock it. True of all but five.
    AllowedInShops = 5,
    /// Displays a number, which is `display_amount`.
    ShowsCounter = 6,
    /// Has a condition on being offered at all: `IsAllowed` takes the
    /// run state and 20 relics override it. What the condition *is* is
    /// code and gets ported by hand; that there is one is the fact a
    /// reward roll needs before it can offer anything.
    GatedInRun = 7,
    /// The same, for Neow's opening choice. Two relics override it.
    GatedAtNeow = 8,
}

/// The flags a relic has, and the ones it works out at the time.
///
/// `IsUsedUp` and `ShowCounter` are `virtual` and some relics decide
/// them from combat state — ten and eighteen of them.
#[derive(Clone, Copy, PartialEq, Eq, Hash)]
pub struct RelicFlags {
    /// The flags that are set. A computed flag is never in here.
    yes: u16,
    /// The flags the model decides at the time.
    computed: u16,
}

impl RelicFlags {
    /// Every flag, in bit order.
    const MEMBERS: [RelicFlag; 9] = [
        RelicFlag::UsedUp,
        RelicFlag::UponPickup,
        RelicFlag::SpawnsPets,
        RelicFlag::Stackable,
        RelicFlag::AddsPet,
        RelicFlag::AllowedInShops,
        RelicFlag::ShowsCounter,
        RelicFlag::GatedInRun,
        RelicFlag::GatedAtNeow,
    ];

    /// The flags a model sets, and the ones it computes.
    ///
    /// A flag in both lists is a contradiction, and this is a `const
    /// fn` called from a `const`, so saying so fails the build rather
    /// than the run.
    pub const fn new(yes: &[RelicFlag], computed: &[RelicFlag]) -> Self {
        let mut set = 0u16;
        let mut i = 0;
        while i < yes.len() {
            set |= 1u16 << yes[i] as u8;
            i += 1;
        }

        let mut asked = 0u16;
        i = 0;
        while i < computed.len() {
            asked |= 1u16 << computed[i] as u8;
            i += 1;
        }

        assert!(set & asked == 0, "a flag cannot be both set and computed");
        Self {
            yes: set,
            computed: asked,
        }
    }

    /// One flag: the answer, or the cue to ask for it.
    ///
    /// There is no `contains`. A computed flag has no answer until
    /// something asks the model, and a `bool` would have to invent
    /// one.
    pub const fn get(self, flag: RelicFlag) -> Field<bool> {
        let bit = 1u16 << flag as u8;
        if self.computed & bit != 0 {
            return Field::Computed;
        }
        Field::Constant(self.yes & bit != 0)
    }
}

impl std::fmt::Debug for RelicFlags {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let mut set = f.debug_set();
        let mut i = 0;
        while i < Self::MEMBERS.len() {
            let flag = Self::MEMBERS[i];
            match self.get(flag) {
                Field::Constant(true) => {
                    set.entry(&flag);
                }
                Field::Computed => {
                    set.entry(&format_args!("{flag:?}: computed"));
                }
                Field::Constant(false) => {}
            }
            i += 1;
        }
        set.finish()
    }
}

/// What a merchant charges, or that there is no such thing.
///
/// `MerchantCost` returns 999999999 for a relic that is not for sale,
/// which is a sentinel and not a price: nothing should do arithmetic
/// on it, and a shop comparing a player's gold against it would be
/// comparing against a number that means never.
///
/// Read per relic rather than derived from rarity. The base
/// implementation maps Ancient, Starter and Event to the sentinel, but
/// nine relics override it — so nine of the 35 Event-rarity relics do
/// have a price.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Price {
    Gold(u16),
    NotSold,
}

/// What is true of a relic with no run in progress.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct RelicData {
    pub rarity: RelicRarity,
    /// Flat: both cost properties were read at all eleven ascension
    /// levels and neither moved.
    pub price: Price,
    pub flags: RelicFlags,
    /// The number a relic with `ShowsCounter` displays.
    ///
    /// `Constant(0)` or `Computed` and nothing else: every relic
    /// that shows a number works it out, and the 260 that do not
    /// show one all report zero.
    pub display_amount: Field<u16>,
}
